const success=successCategories.map(category=>formalDone.filter(r=>r.category===category).sort((a,b)=>b.score.core_score-a.score.core_score)[0]);
const clip=(s,n=320)=>String(s??'').replace(/\s+/g,' ').slice(0,n)+(String(s??'').length>n?'…':'');
const caseIndex=[];
let successMd='# Success cases\n\nThese five compact cases are selected across different capabilities. Snippets are intentionally bounded; the raw supplemental results remain the machine source.\n\n';
for(const r of success){
  const ev=(r.visible_context||[]).slice(0,3).map(x=>({source_id:x.source_id,source_agents:x.source_agents,text:clip(x.text,360)}));
  const data={scenario_id:r.scenario_id,category:r.category,question:r.question,key_original_events:ev,candidate_pool_evidence:'The archived terminal result exposes the final visible context but not a separately serialized per-case Candidate Pool snapshot.',final_20_evidence:'MISSING — no per-case Final-20 layer was archived in the supplemental result record.',answer_top_10:ev,structured_answer_summary:clip(r.structured_answer?.answer,500),key_metrics:r.score,why_success:`Completed with core_score=${r.score.core_score}; selected evidence and structured answer retained source identifiers.`,source_file:sourcePath(stages.formal.dir)};
  json(`cases/case-evidence/${r.scenario_id}.json`,data); caseIndex.push({case_type:'success',scenario_id:r.scenario_id,category:r.category,mode:r.mode,status:r.status,core_score:r.score.core_score,evidence_file:`cases/case-evidence/${r.scenario_id}.json`,source_file:data.source_file});
  successMd+=`## ${r.scenario_id}\n\n- Category: ${categoryNames[r.category]}\n- Question: ${clip(r.question,240)}\n- Key event: ${ev[0]?.text||'UNKNOWN — no visible context'}\n- Answer summary: ${data.structured_answer_summary}\n- Core score: ${r.score.core_score}\n- Why successful: ${data.why_success}\n- Evidence: \`case-evidence/${r.scenario_id}.json\`\n\n`;
}
write('cases/success-cases.md',successMd);
let failMd='# Failure cases\n\nAll three terminal errors are retained. None entered scoring; each affects the corresponding completion/error count.\n\n';
for(const e of errorRows){json(`cases/case-evidence/${e.scenario_id}-${e.mode}-failure.json`,e);caseIndex.push({case_type:'failure',scenario_id:e.scenario_id,category:e.category,mode:e.mode,status:'error',core_score:'NOT SCORED',evidence_file:`cases/case-evidence/${e.scenario_id}-${e.mode}-failure.json`,source_file:e.source_file});failMd+=`## ${e.scenario_id} (${e.mode})\n\n- Attempts: 3; requested max_tokens: ${e.requested_max_tokens}\n- Completion tokens: ${e.completion_tokens}; finish_reason: ${e.finish_reason}\n- Error: ${e.json_parse_error}\n- Scoring: not entered; retained as an error.\n- Classification: ${e.classification}\n- Paper reporting: ${e.paper_reporting}\n\n`;}
